// Fuzz Mozzi's SampleHuffman (SampleHuffman.h): the Huffman bitstream decoder behind next().
//
// The Huffman tree is compile-time data generated by extras/python/audio2huff.py, so it is fixed
// here to a real shipped table (samples/a-bomb-huffman.h). The fuzz input is the sound data, held in
// an exact-size heap buffer. SampleHuffman's contract is that SOUNDDATA_BITS ends on a code boundary
// (audio2huff writes the bit count of the complete stream), so the harness walks the same tree over
// the input first and passes the bit count of the last complete code, like audio2huff would.
#include "fuzz_common.h"
#include <MozziHeadersOnly.h>
#include <SampleHuffman.h>
#include <samples/a-bomb-huffman.h>

static uint32_t complete_bits(const uint8_t *d, uint32_t nbits) {
  uint32_t pos = 0, last = 0;
  while (pos < nbits) {
    const int16_t *h = huffman;
    bool done = false;
    do {
      if (pos >= nbits) return last;          // code cut off by the end of the data
      if ((d[pos >> 3] >> (7 - (pos & 7))) & 1) { int16_t o = *h; h += o ? o + 1 : 2; }
      pos++;
      done = (*h++ == 0) ? true : false;
    } while (!done);
    last = pos;
  }
  return last;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  if (size < 2 || size > 65536) return 0;
  uint8_t ctl = data[0];
  size_t n = size - 1;
  uint8_t *buf = new uint8_t[n];
  memcpy(buf, data + 1, n);
  uint32_t bits = complete_bits(buf, (uint32_t)n * 8);
  if (bits == 0) { delete[] buf; return 0; }  // no complete code: not a sound stream audio2huff can emit
  SampleHuffman s(buf, huffman, bits);
  if (ctl & 1) s.setLoopingOn();
  s.start();
  volatile int32_t acc = 0;
  uint32_t steps = (uint32_t)n * 8 * ((ctl & 1) ? 2 : 1) + 16;
  for (uint32_t i = 0; i < steps; i++) {
    acc += s.next();
    if ((ctl & 2) && i == steps / 2) s.start();
  }
  delete[] buf;
  return 0;
}
